cat > /root/direct-sync/reg_by_account.py <<'PY'
import sys,os,collections,json,time
sys.path.insert(0,"/root/unitex-finrep/engine"); os.chdir("/root/unitex-finrep")
from odata_client import ODataClient
c=ODataClient()
acc={a["Ref_Key"]:((a.get("Code") or "").strip(),(a.get("Description") or "").strip())
     for a in c.list("ChartOfAccounts_Хозрасчетный", select=["Ref_Key","Code","Description"])}
vid={v["Ref_Key"]:(v.get("Description") or "").strip() for v in c.list("Catalog_ВидОплаты", select=["Ref_Key","Description"])}
t=time.time(); n=0
dr=collections.Counter(); cr=collections.Counter(); sdr=collections.defaultdict(float); scr=collections.defaultdict(float)
withvid=collections.Counter()
for r in c.list("AccountingRegister_Хозрасчетный_RecordType",
                select=["Period","AccountDr_Key","AccountCr_Key","Сумма","ВалютнаяСуммаDr","ВалютнаяСуммаCr","ВидОплаты_Key"]):
    n+=1
    a=acc.get(r.get("AccountDr_Key")); b=acc.get(r.get("AccountCr_Key"))
    if a: dr[a]+=1; sdr[a]+=float(r.get("ВалютнаяСуммаDr") or 0)
    if b: cr[b]+=1; scr[b]+=float(r.get("ВалютнаяСуммаCr") or 0)
    if vid.get(r.get("ВидОплаты_Key")): withvid[(a or ("?","?"))]+=1
    if n%50000==0: print("  ...",n,"рухів, %.0fс"%(time.time()-t),flush=True)
print("УСЬОГО РУХІВ У РЕГІСТРІ: %d за %.0fс"%(n,time.time()-t),flush=True)
print("\nПО ДЕБЕТУ (рахунок | рухів | сума вал):")
for a,cnt in dr.most_common(25): print("   %-6s %-34s %6d  %14.2f"%(a[0],a[1][:34],cnt,sdr[a]))
print("\nПО КРЕДИТУ:")
for a,cnt in cr.most_common(25): print("   %-6s %-34s %6d  %14.2f"%(a[0],a[1][:34],cnt,scr[a]))
print("\nрухів із заповненим «Вид оплати» по рахунках дебету:")
for a,cnt in withvid.most_common(12): print("   %-6s %-34s %6d"%(a[0],a[1][:34],cnt))
PY
cd /root/direct-sync && nohup /root/unitex-finrep/.venv/bin/python reg_by_account.py > /root/direct-sync/reg_acc.out 2>&1 &
sleep 105; tail -32 /root/direct-sync/reg_acc.out
